import brand from './brand.json';
import appIcon from './assets/app-icon.png';
import './manual.css';
import {cloneJson,applyRoleSizes,reorderMembers} from './model.js';
import {createLaunchQueue} from './launch_queue.js';
const updateInfo=ref({phase:'idle',message:'尚未检查更新',auto_check:true});
const updateBusy=computed(()=>['checking','downloading'].includes(updateInfo.value.phase));
async function updateAction(action,payload){try{const r=await window.pywebview.api.update(action,payload);if(!r.ok)throw Error(r.error);updateInfo.value=r.data}catch(e){tell(e.message)}}
const proxyRiskNotice='IP 代理功能未经完整测试，不保证可行性、兼容性或稳定性。检测通过不代表游戏所有流量均已代理，可能出现连接失败、掉线或客户端异常，请谨慎使用。';
const deviceRiskNotice='设备接口隔离功能未经完整测试，不保证可行性、兼容性或稳定性，也不保证形成独立硬件身份。可能出现登录异常或客户端退出，请谨慎使用。';
const cfg=ref({accounts:[],pending:[],layout_plans:{},window_profiles:{}}), states=ref({}), screens=ref([]), logs=ref([]), ready=ref(false), busy=ref(false), toast=ref('');
const checked=ref([]), selected=ref(''), expanded=ref(new Set(['未分组'])), screen=ref(''), planName=ref('默认方案'), gamePath=ref(''), profiles=ref({});
const settings=ref({width:960,height:540,columns:3,gap:8,padding:8,aspect:true,mode:'网格排列'}), auto=ref(false);
const preview=ref({rects:{},work:[0,0,1920,1080],frame:[0,0]}), previewError=ref(''), modal=ref(''), sources=ref([]), syncRoot=ref(''), syncChecked=ref([]);
const editor=ref({}), readCandidate=ref(null), readId=ref(''), binding=ref(''), reading=ref(false), filter=ref(''), groupName=ref(''), groupOld=ref(''), groupAction=ref('new');
const pathExpanded=ref(false), sizeDraft=ref({width:960,height:540});
const detectingGame=ref(false), detectedGames=ref([]), gameDetectMessage=ref(''), purgeTarget=ref(null), purgeInfo=ref(null), purgeError=ref('');
const statusFilter=ref('全部'), metaDraft=ref({note:'',group:'未分组'}), removeIds=ref([]);
const page=ref('plans'), memberDraft=ref([]), activePlan=ref(''), planBaseline=ref('');
const roleView=ref('cards'), viewSaving=ref(false);
const memberView=ref('list'), memberViewSaving=ref(false);
async function chooseMemberView(view){if(view===memberView.value||memberViewSaving.value)return;const old=memberView.value;memberView.value=view;memberViewSaving.value=true;try{await raw('member_view',{view})}catch(e){memberView.value=old;tell(e.message)}finally{memberViewSaving.value=false}}
async function chooseRoleView(view){if(view===roleView.value||viewSaving.value)return;const before=roleView.value;roleView.value=view;viewSaving.value=true;try{await raw('role_view',{view})}catch(e){roleView.value=before;tell(e.message)}finally{viewSaving.value=false}}
const inheritGamePrefs=p=>({mute_all:p?.mute_all??null,skip_intro:p?.skip_intro??null,lowest_graphics:p?.lowest_graphics??null});
const planGamePrefs=ref(inheritGamePrefs()), gamePrefsScope=ref('global');
const prefFields=[{key:'mute_all',label:'声音',on:'强制静音'},{key:'skip_intro',label:'登录动画',on:'关闭动画'},{key:'lowest_graphics',label:'画质',on:'最低画质'}];
const gamePrefs=ref({mute_all:true,skip_intro:true,lowest_graphics:true}), gamePrefsWorking=ref(false);
async function saveGamePrefs(){
  if(gamePrefsScope.value==='plan'){planGamePrefs.value=inheritGamePrefs(gamePrefs.value);modal.value='';tell('已应用到方案草稿，请保存方案');return}
  gamePrefsWorking.value=true;
  try{await raw('game_preferences',{...gamePrefs.value});await refresh(false,true);modal.value='';tell('全局默认已保存，继承这些设置的角色下次启动生效')}catch(e){tell(e.message)}finally{gamePrefsWorking.value=false}
}
const globalGamePrefsSummary=computed(()=>{const p={mute_all:true,skip_intro:true,lowest_graphics:true,...cfg.value.game_preferences};return [p.mute_all?'静音':'',p.skip_intro?'关闭动画':'',p.lowest_graphics?'最低画质':''].filter(Boolean).join(' · ')||'不强制游戏设置'});
const gamePrefsSummary=computed(()=>{const count=Object.values(planGamePrefs.value).filter(v=>v!==null).length;return count?`覆盖 ${count} 项`:'继承角色 / 全局'});
function openGamePrefs(scope='plan'){gamePrefsScope.value=scope;gamePrefs.value=scope==='plan'?inheritGamePrefs(planGamePrefs.value):{mute_all:true,skip_intro:true,lowest_graphics:true,...cfg.value.game_preferences};modal.value='gameprefs'}
const launchDelay=ref(0), batchLaunching=ref(false), batchProgress=ref('');
const queueState=ref({items:[],dispatching:false,message:''}), queueOpen=ref(false);
const queuePending=computed(()=>queueState.value.items.filter(x=>['queued','starting','submitted'].includes(x.status)).length);
const queueReady=computed(()=>queueState.value.items.filter(x=>x.status==='ready').length);
const queueFailed=computed(()=>queueState.value.items.filter(x=>x.status==='failed').length);
const queueBusy=computed(()=>queueState.value.dispatching||queuePending.value>0);
function queueStatus(status){return ({queued:'待提交',starting:'正在提交',submitted:'准备窗口',ready:'已就绪',failed:'失败',cancelled:'已取消',rebind:'需登录绑定'})[status]||status}

const deviceSummaries=ref({}),deviceChecks=ref({}),deviceChecking=ref(false);
const proxies=ref([]), proxyEngine=ref({ready:false,message:'游戏转发未就绪'}), proxyWorking=ref(false), proxyDraft=ref({}), proxyResult=ref(null), bindProxyId=ref(''), bindRoleIds=ref([]);
const dnsResult=ref(null), deleteProxyConfirm=ref(false);
async function deleteProxy(){if(!proxyDraft.value.id||proxyWorking.value)return;proxyWorking.value=true;try{await raw('proxy_delete',{id:proxyDraft.value.id});await refresh(false,true);editProxy(proxies.value[0]||null);tell('本地代理已移除')}catch(e){tell(e.message)}finally{proxyWorking.value=false}}
async function restoreLaoYuLines(){if(proxyWorking.value)return;try{await raw('laoyu_restore',{port:laoyuPort.value});await probeLaoYu()}catch(e){tell(e.message)}}
async function testProxyDns(){if(!proxyDraft.value.id||proxyWorking.value)return;proxyWorking.value=true;dnsResult.value=null;try{dnsResult.value=await raw('proxy_dns_test',{id:proxyDraft.value.id})}catch(e){dnsResult.value={ok:false,error:e.message}}finally{proxyWorking.value=false}}
const backendDraft=ref('builtin'), laoyuPort=ref(22999), laoyuInfo=ref(null);
const proxyRoutes=computed(()=>proxyEngine.value.routes||{});
const proxyActiveCount=computed(()=>Object.values(proxyRoutes.value).filter(x=>x.active).length);
const proxySessions=computed(()=>Object.values(proxyRoutes.value).filter(x=>x.active||x.phase==='failed'||x.phase==='cancelled').slice(-6));
function proxyPhase(phase){return ({idle:'尚未启动',starting:'正在准备',syncing_proxy:'正在同步老鱼线路',binding_proxy:'正在绑定游戏 PID',creating_suspended_game:'正在准备游戏',waiting_administrator:'等待管理员授权与转发保护',running_tcp_trial:'内置 TCP 代理运行中',running_laoyu:'老鱼专业版代理运行中',game_exited:'已结束',cancelled:'已取消',failed:'代理启动失败',broker_disconnected:'代理组件断开，正在关闭角色',waiting_owned_game_exit_before_release:'等待游戏退出后释放保护',waiting_owned_family_exit_before_release:'等待游戏及子进程退出后释放保护',not_started:'代理进程已结束'})[phase]||phase||'尚未启动'}
async function saveProxyBackend(){proxyWorking.value=true;try{await raw('proxy_backend',{backend:backendDraft.value,port:laoyuPort.value});await refresh(false,true);tell('代理执行方式已保存')}catch(e){tell(e.message)}finally{proxyWorking.value=false}}
async function probeLaoYu(){const chosen=proxyDraft.value.id;proxyWorking.value=true;laoyuInfo.value=null;try{laoyuInfo.value=await raw('laoyu_probe',{port:laoyuPort.value});await refresh(false,true);editProxy(proxies.value.find(p=>p.id===chosen)||proxies.value[0]||null)}catch(e){laoyuInfo.value={ok:false,error:e.message}}finally{proxyWorking.value=false}}
async function syncLaoYu(){if(!proxyDraft.value.id)return;proxyWorking.value=true;try{await raw('laoyu_sync',{id:proxyDraft.value.id});tell('代理已同步到老鱼；已有匹配线路会直接复用')}catch(e){tell(e.message)}finally{proxyWorking.value=false}}

function proxyOptionLabel(p){return `${p.name} · ${p.host}:${p.port}${p.laoyu_sign?' · 老鱼':''}`}
function proxyLabel(id){const p=proxies.value.find(p=>p.id===id);return id?(p?proxyOptionLabel(p):'代理已缺失'):'直连'}
function editProxy(p=null){deleteProxyConfirm.value=false;dnsResult.value=null;proxyDraft.value={id:p?.id||'',laoyu_managed:!!p?.laoyu_managed,laoyu_sign:p?.laoyu_sign||'',laoyu_exit_ip:p?.laoyu_exit_ip||'',laoyu_area:p?.laoyu_area||'',name:p?.name||'',host:p?.host||'',port:p?.port||1080,enabled:p?.enabled??true,username:'',password:'',clear_auth:false};proxyResult.value=p?.last_test||null}
function openProxies(){editProxy(proxies.value[0]||null);backendDraft.value=proxyEngine.value.backend||'builtin';laoyuPort.value=proxyEngine.value.laoyu_port||22999;laoyuInfo.value=null;modal.value='proxies';if(backendDraft.value==='laoyu')probeLaoYu()}
async function saveProxy(){proxyWorking.value=true;try{const id=await raw('proxy_save',{...proxyDraft.value});proxyDraft.value.password='';proxyDraft.value.username='';await refresh(false,true);editProxy(proxies.value.find(p=>p.id===id));tell('代理已保存，认证信息使用当前 Windows 用户加密')}catch(e){tell(e.message)}finally{proxyWorking.value=false}}
async function testProxy(id=proxyDraft.value.id){if(!id||proxyWorking.value)return;proxyWorking.value=true;proxyResult.value=null;try{proxyResult.value=await raw('proxy_test',{id});await refresh(false,true)}catch(e){tell(e.message)}finally{proxyWorking.value=false}}
async function closeProxyRole(id){id=id||proxyEngine.value.trial?.role_id;if(!id)return;try{await execute('close',{ids:[id],force:true});await refresh(false,true);tell('已请求关闭代理角色并清理连接')}catch{}}
function openProxyBinding(){bindRoleIds.value=[...checked.value];bindProxyId.value='';modal.value='proxybind'}
async function bindProxies(){try{const n=await execute('proxy_bind',{ids:bindRoleIds.value,proxy_id:bindProxyId.value});await refresh(false,true);modal.value='';tell(`已更新 ${n} 个角色的代理绑定`)}catch{}}
let workspaceSelection=null;
const launchFeedback=ref({}), serverLaunches=ref({});
const launchQueue=createLaunchQueue({
  preflight:(_ids,context)=>raw('launch_preflight',{ids:context.layoutIds}),
  dispatch:async(id,request_id,context)=>{
    launchFeedback.value[id]={phase:'requesting',error:''};
    try{
      const result=await raw('start',{...context.options,ids:[id],layout_ids:context.layoutIds,request_id});
      const row=result?.find(x=>x.id===id);
      if(!row)throw Error('未取得启动结果，请检查运行记录');
      launchFeedback.value[id]={phase:row.error?'failed':'done',error:row.error||''};
      if(row.pending)binding.value=id;
      if(row.needs_rebind){selected.value=id;modal.value='rebind'}
      await refresh(false,true);
      return row;
    }catch(e){launchFeedback.value[id]={phase:'failed',error:e.message};throw e}
  },
  onChange:value=>{queueState.value=value;batchLaunching.value=value.dispatching;batchProgress.value=value.message}
});
function stopLaunchQueue(){launchQueue.stop();tell('已停止后续启动，已经提交的角色继续准备')}
async function retryLaunchQueue(){if(queueBusy.value)return;queueOpen.value=true;try{await launchQueue.retry()}catch(e){tell(e.message)}}
function clearLaunchQueue(){if(launchQueue.clear())queueOpen.value=false}
function isLaunching(id){return (proxyRoutes.value[id]?.active&&['starting','syncing_proxy','binding_proxy','creating_suspended_game','waiting_administrator'].includes(proxyRoutes.value[id]?.phase))||launchFeedback.value[id]?.phase==='requesting'||serverLaunches.value[id]?.phase==='starting'}
function launchError(id){return launchFeedback.value[id]?.error||serverLaunches.value[id]?.error||''}
function roleLaunchLabel(a){return isLaunching(a.id)?'正在启动…':states.value[a.id]?.running?'定位窗口':!a.confirmed||status(a)==='需重新绑定'?'登录绑定':launchError(a.id)?'重试':'启动'}
const draggedRole=ref(''), roleDropGroup=ref(''), floatingRole=ref(null), floatPoint=ref({x:0,y:0}), settlingRole=ref(false), landedRole=ref(''), floatingEl=ref(null), dragKind=ref('role'), landedPlan=ref('');
let blankDragImage=null, roleDropPending=false, landingTimer=null, motionFrame=0, motionX=0, motionY=0;
function moveFloat(x,y){motionX=x;motionY=y;if(motionFrame)return;motionFrame=requestAnimationFrame(()=>{motionFrame=0;if(floatingEl.value)floatingEl.value.style.transform=`translate3d(${motionX}px,${motionY}px,0)`})}
function hideNativeGhost(e){blankDragImage=document.createElement('canvas');blankDragImage.width=blankDragImage.height=1;blankDragImage.style.cssText='position:fixed;left:0;top:0;pointer-events:none';document.body.append(blankDragImage);e.dataTransfer.setDragImage(blankDragImage,0,0)}
function trackRoleDrag(e){if((!draggedRole.value&&!draggedPlan.value&&!draggedMember.value)||roleDropPending||(!e.clientX&&!e.clientY))return;moveFloat(e.clientX+16,e.clientY+12)}
function clearRoleFloat(){if(motionFrame)cancelAnimationFrame(motionFrame);motionFrame=0;floatingRole.value=null;settlingRole.value=false;blankDragImage?.remove();blankDragImage=null}
function beginRoleDrag(e,id){if(busy.value||roleDropPending||e.target.closest('button,input')){e.preventDefault();return}clearTimeout(landingTimer);clearRoleFloat();dragKind.value='role';landedRole.value='';settlingRole.value=false;draggedRole.value=id;floatingRole.value=roles.value.find(a=>a.id===id);floatPoint.value={x:e.clientX+16,y:e.clientY+12};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',id);hideNativeGhost(e)}
function hoverRoleGroup(e,name){if(!draggedRole.value)return;e.preventDefault();e.dataTransfer.dropEffect='move';roleDropGroup.value=name;trackRoleDrag(e)}
function finishRoleDrag(){draggedRole.value='';roleDropGroup.value='';if(!roleDropPending)clearRoleFloat()}
async function dropRoleGroup(e,name){if(!draggedRole.value)return;e.preventDefault();e.stopPropagation();const id=draggedRole.value,role=roles.value.find(a=>a.id===id);if(!role||!knownGroups.value.includes(name)||(role.group||'未分组')===name){finishRoleDrag();return}roleDropPending=true;settlingRole.value=true;finishRoleDrag();try{await execute('group',{kind:'assign',name,ids:[id]});expanded.value.add(name);await refresh(false,true);await nextTick();const target=document.querySelector(`[data-role-id="${CSS.escape(id)}"]`);if(target){target.scrollIntoView({block:'nearest',behavior:'instant'});const rect=target.getBoundingClientRect();moveFloat(rect.left,rect.top);landedRole.value=id}tell(`已将 ${role.nickname||role.name} 移入“${name}”`);landingTimer=setTimeout(()=>{clearRoleFloat();landedRole.value=''},180)}catch{clearRoleFloat()}finally{roleDropPending=false}}

onMounted(()=>document.addEventListener('dragover',trackRoleDrag));
onUnmounted(()=>{document.removeEventListener('dragover',trackRoleDrag);clearTimeout(landingTimer);clearRoleFloat()});
let pollTimer,readTimer,previewTimer,toastTimer,drag=null,serial=0;
const roles=computed(()=>[...cfg.value.accounts,...cfg.value.pending]);
const visible=computed(()=>roles.value.filter(a=>`${a.nickname||a.name} ${a.server||''} ${a.note||''}`.toLowerCase().includes(filter.value.toLowerCase())&&(statusFilter.value==='全部'||status(a)===statusFilter.value)));
const removed=computed(()=>cfg.value.removed_roles||[]);
const removing=computed(()=>roles.value.filter(a=>removeIds.value.includes(a.id)));
const knownGroups=computed(()=>[...new Set(['未分组',...(cfg.value.groups||[]),...roles.value.map(a=>a.group||'未分组')])]);
const groups=computed(()=>[...new Set(['未分组',...(cfg.value.groups||[]),...visible.value.map(a=>a.group||'未分组')])].map(name=>({name,roles:visible.value.filter(a=>(a.group||'未分组')===name)})));
const running=computed(()=>Object.values(states.value).filter(s=>s.running).length);
const chosen=computed(()=>roles.value.find(a=>a.id===selected.value));
const targets=computed(()=>checked.value.length?checked.value.filter(id=>roles.value.some(a=>a.id===id)):(selected.value?[selected.value]:[]));
const draggedPlan=ref(''), dropPlan=ref('');
const plans=computed(()=>{const keys=Object.keys(cfg.value.layout_plans||{});return [...new Set([...(cfg.value.plan_order||[]).filter(n=>keys.includes(n)),...keys])]});
async function persistPlanOrder(names){const previous=cfg.value.plan_order;cfg.value.plan_order=[...names];try{await execute('plan_order',{names});return true}catch{cfg.value.plan_order=previous;return false}}
function beginPlanDrag(e,name){if(busy.value||roleDropPending){e.preventDefault();return}clearTimeout(landingTimer);clearRoleFloat();dragKind.value='plan';landedPlan.value='';draggedPlan.value=name;floatingRole.value={name,server:`${cfg.value.layout_plans[name]?.roles?.length||0} 个角色`};floatPoint.value={x:e.clientX+16,y:e.clientY+12};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',name);hideNativeGhost(e)}
function hoverPlanDrag(e,name){if(!draggedPlan.value)return;e.preventDefault();e.dataTransfer.dropEffect='move';if(dropPlan.value!==name)dropPlan.value=name;trackRoleDrag(e)}
function finishPlanDrag(){draggedPlan.value='';dropPlan.value='';if(!roleDropPending)clearRoleFloat()}
async function dropScheme(e,name){e.preventDefault();const from=draggedPlan.value;if(!from||from===name){finishPlanDrag();return}const names=plans.value.filter(n=>n!==from),rect=e.currentTarget.getBoundingClientRect();names.splice(names.indexOf(name)+(e.clientY>rect.top+rect.height/2?1:0),0,from);roleDropPending=true;settlingRole.value=true;finishPlanDrag();try{if(await persistPlanOrder(names)){await nextTick();const target=document.querySelector(`[data-plan-name="${CSS.escape(from)}"]`);if(target){const r=target.getBoundingClientRect();moveFloat(r.left,r.top);landedPlan.value=from}landingTimer=setTimeout(()=>{clearRoleFloat();landedPlan.value=''},180)}else clearRoleFloat()}finally{roleDropPending=false}}
async function stepScheme(name,delta){if(busy.value)return;const names=[...plans.value],i=names.indexOf(name),j=i+delta;if(j<0||j>=names.length)return;[names[i],names[j]]=[names[j],names[i]];await persistPlanOrder(names)}

const members=computed(()=>checked.value.map(id=>roles.value.find(a=>a.id===id)).filter(Boolean));
const draggedMember=ref(''), dropMember=ref(''), memberDropAfter=ref(false), landedMember=ref('');
function beginMemberDrag(e,id){if(busy.value||batchLaunching.value||roleDropPending||e.target.closest('button,input')){e.preventDefault();return}clearTimeout(landingTimer);clearRoleFloat();dragKind.value='member';landedMember.value='';draggedMember.value=id;floatingRole.value=roles.value.find(a=>a.id===id);floatPoint.value={x:e.clientX+16,y:e.clientY+12};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',id);hideNativeGhost(e)}
function hoverMemberDrag(e,id){if(!draggedMember.value)return;e.preventDefault();e.dataTransfer.dropEffect='move';const r=e.currentTarget.getBoundingClientRect();dropMember.value=id;memberDropAfter.value=memberView.value==='cards'?e.clientX>r.left+r.width/2:e.clientY>r.top+r.height/2;trackRoleDrag(e)}
function finishMemberDrag(){draggedMember.value='';dropMember.value='';if(!roleDropPending)clearRoleFloat()}
async function dropMemberOrder(e,id){if(!draggedMember.value)return;e.preventDefault();e.stopPropagation();const from=draggedMember.value;if(from===id){finishMemberDrag();return}roleDropPending=true;settlingRole.value=true;checked.value=reorderMembers(checked.value,from,id,memberDropAfter.value);finishMemberDrag();try{await nextTick();const target=document.querySelector(`[data-member-id="${CSS.escape(from)}"]`);if(target){const r=target.getBoundingClientRect();moveFloat(r.left,r.top);landedMember.value=from}landingTimer=setTimeout(()=>{clearRoleFloat();landedMember.value=''},180)}finally{roleDropPending=false}}
function stepMember(id,delta){if(busy.value||batchLaunching.value)return;const i=checked.value.indexOf(id),j=i+delta;if(i<0||j<0||j>=checked.value.length)return;checked.value=reorderMembers(checked.value,id,checked.value[j],delta>0)}

function planFingerprint(){return JSON.stringify({name:planName.value,ids:checked.value,settings:settings.value,profiles:profiles.value,screen:screen.value,auto:auto.value,launch_delay:launchDelay.value,game_preferences:planGamePrefs.value})}
const planDirty=computed(()=>planBaseline.value!==''&&planFingerprint()!==planBaseline.value);
function tell(message){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',6000)}
async function raw(action,p={}){const r=await window.pywebview.api.command(action,p);if(!r.ok)throw Error(r.error);return r.data}
async function execute(action,p={}){busy.value=true;try{return await raw(action,p)}catch(e){tell(e.message);throw e}finally{busy.value=false}}
async function refresh(initial=false,force=false){if(!window.pywebview?.api)return;if(!initial&&!force&&(draggedRole.value||draggedPlan.value||draggedMember.value||roleDropPending||settlingRole.value))return;const s=await window.pywebview.api.snapshot();const previous=new Map([...cfg.value.accounts,...cfg.value.pending].map(r=>[r.id,r.proxy_id||'']));for(const role of [...s.config.accounts,...s.config.pending]){if(previous.has(role.id)&&previous.get(role.id)!==(role.proxy_id||''))delete launchFeedback.value[role.id]}if(s.updates)updateInfo.value=s.updates;cfg.value=s.config;states.value=s.states;deviceSummaries.value=s.devices||{};proxies.value=s.proxies||[];proxyEngine.value=s.proxy_engine||proxyEngine.value;serverLaunches.value=s.launches||{};launchQueue.reconcile(s.launches||{},s.proxy_engine?.routes||{});screens.value=s.screens;logs.value=s.logs;checked.value=checked.value.filter(i=>roles.value.some(a=>a.id===i));if(initial){gamePrefs.value={mute_all:true,skip_intro:true,lowest_graphics:true,...s.config.game_preferences};const savedMember=s.config.ui_preferences?.member_view;if(['cards','list','table'].includes(savedMember))memberView.value=savedMember;const savedView=s.config.ui_preferences?.role_view;if(['cards','list','table'].includes(savedView))roleView.value=savedView;gamePath.value=s.config.game||'';syncRoot.value=s.config.pinganzhi_root||s.source_root;profiles.value=cloneJson(s.config.window_profiles||{});screen.value=s.screens[0]?.id||'';if(plans.value.length){planName.value=plans.value[0];loadPlan()}else{newPlan(true)}}}
function payload(){return {ids:targets.value,settings:cloneJson(settings.value),profiles:cloneJson(profiles.value),screen:screen.value,auto:auto.value,launch_delay:launchDelay.value,game_preferences:cloneJson(planGamePrefs.value)}}
function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(updatePreview,130)}
async function updatePreview(){if(!ready.value)return;const n=++serial;try{const r=await raw('preview',payload());if(n===serial){preview.value=r;previewError.value=''}}catch(e){if(n===serial)previewError.value=e.message}}
watch([checked,selected,settings,profiles,screen],schedulePreview,{deep:true});
watch(()=>[sizeDraft.value.width,settings.value.aspect],()=>{if(settings.value.aspect)sizeDraft.value.height=Math.round(Number(sizeDraft.value.width)*9/16)});
function groupCheck(g){return g.roles.length>0&&g.roles.every(a=>checked.value.includes(a.id))}
function toggleGroup(g){const s=new Set(checked.value);if(groupCheck(g))g.roles.forEach(a=>s.delete(a.id));else g.roles.forEach(a=>s.add(a.id));checked.value=[...s]}
function toggleExpanded(name){const s=new Set(expanded.value);s.has(name)?s.delete(name):s.add(name);expanded.value=s}
function nameFor(id){const a=roles.value.find(a=>a.id===id);return a?.nickname||a?.name||'角色'}
function previewTitle(id,r){const a=roles.value.find(a=>a.id===id);return `${nameFor(id)} · ${a?.server||'待确认区服'}\n${r[2]} × ${r[3]} · ${states.value[id]?.running?'运行中':'未运行'}`}
function roleSize(a){const p=profiles.value[a.id]||settings.value;return `${p.width||settings.value.width} × ${p.height||settings.value.height}`}
function status(a){if(isLaunching(a.id))return a.proxy_id?'代理准备中':'正在启动';if(states.value[a.id]?.running)return proxyRoutes.value[a.id]?.active?(proxyRoutes.value[a.id]?.provider==='laoyu'?'老鱼代理':'TCP 代理'):'运行中';if(a.proxy_id)return '代理已绑定';if(a.imported&&a.cache_mode!=='fresh-single-role')return '需重新绑定';return a.confirmed?'已就绪':'待登录确认'}
async function launchRole(id,withinScheme=false){if(batchLaunching.value||isLaunching(id))return;launchFeedback.value[id]={phase:'requesting',error:''};try{const r=await execute(withinScheme?'start_member':'single_start',withinScheme?{...payload(),id}:{id});selected.value=id;launchFeedback.value[id]={phase:'done',error:''};if(r.needs_rebind){modal.value='rebind';return}if(r.pending){binding.value=id;tell('请登录并进入庭院，随后确认角色信息')}else tell(r.proxy?(proxyEngine.value.backend==='laoyu'?'正在准备老鱼线路并绑定角色':'正在准备 TCP 代理，请完成管理员授权'):r.focused?'已定位游戏窗口':withinScheme?'正在启动，将使用本方案的尺寸和位置':'正在等待游戏窗口，默认 960 × 540');await refresh()}catch(e){launchFeedback.value[id]={phase:'failed',error:e.message}}}

function editMeta(id){selected.value=id;const a=roles.value.find(a=>a.id===id);metaDraft.value={note:a.note||'',group:a.group||'未分组',proxy_id:a.proxy_id||'',device_identity:a.device_identity?cloneJson(a.device_identity):null,game_preferences:inheritGamePrefs(a.game_preferences)};modal.value='meta'}
function devicePhaseLabel(phase){return ({off:'保存配置：未启用',configured:'已配置，待下次启动',loaded:'本次启动已加载，尚未核验',unverified:'当前窗口未核验',checked:'上次核验时已启用',component_inactive:'上次核验时未启用',check_failed:'无法确认当前状态'})[phase]||'尚未核验'}
function deviceStatusFor(id){const summary=deviceSummaries.value[id]||{phase:'off'};const checked=deviceChecks.value[id];if(['loaded','unverified'].includes(summary.phase)&&checked?.pid===summary.pid&&checked?.stamp===summary.stamp)return checked;return summary}
async function checkDevice(){if(deviceChecking.value)return;const id=selected.value;deviceChecking.value=true;try{deviceChecks.value[id]=await raw('device_check',{id})}catch(e){tell(e.message)}finally{deviceChecking.value=false}}
async function generateDeviceProfile(){if(metaDraft.value.device_identity&&!window.confirm('重新生成会改变设备参数。保存后，角色下次启动将使用新参数。确定继续吗？'))return;try{metaDraft.value.device_identity=await execute('device_profile',{id:selected.value});tell('已生成独立设备参数，默认关闭；保存角色后保留')}catch{}}
async function saveMeta(){try{await execute('role_meta',{ids:[selected.value],...metaDraft.value});modal.value='';await refresh();tell('角色设置已保存')}catch{}}
function askRemove(ids){if(!ids.length){tell('请先勾选要删除的角色');return}removeIds.value=[...ids];modal.value='remove'}
async function removeRoles(){try{const n=await execute('remove_roles',{ids:removeIds.value});if(removeIds.value.includes(selected.value))selected.value='';if(removeIds.value.includes(binding.value))binding.value='';readCandidate.value=null;modal.value='';await refresh();profiles.value=cloneJson(cfg.value.window_profiles||{});await updatePreview();tell(`已删除 ${n} 个角色，缓存保留，可从已移除列表恢复`)}catch{}}
async function restoreRole(id){try{await execute('restore_role',{id});await refresh();profiles.value=cloneJson(cfg.value.window_profiles||{});tell('角色已恢复；需要时重新加入排列方案')}catch{}}
function openGroup(kind,name=''){groupAction.value=kind;groupOld.value=name;groupName.value=kind==='rename'?name:'';modal.value='group'}
async function saveGroup(){try{const p={kind:groupAction.value,name:groupAction.value==='rename'?groupOld.value:groupName.value,new:groupName.value,ids:targets.value};await execute('group',p);expanded.value.add(groupName.value);modal.value='';await refresh()}catch{}}
async function ungroup(name){try{await execute('group',{kind:'remove',name});await refresh()}catch{}}
async function chooseGame(){const path=await window.pywebview.api.choose_folder();if(path)gamePath.value=path}
async function applySizes(){if(!checked.value.length){tell('请先为方案添加角色');return}try{profiles.value=applyRoleSizes(profiles.value,checked.value,sizeDraft.value,settings.value.aspect);tell('已修改本方案的窗口尺寸，请保存方案；其他方案不受影响')}catch(e){tell(e.message)}}
async function detectGame(automatic=false){if(detectingGame.value)return;const draft=gamePath.value;detectingGame.value=true;gameDetectMessage.value='正在检查游戏安装位置…';try{const result=await raw('detect_game',{automatic});detectedGames.value=result.candidates||[];if(result.saved){await refresh(false,true);if(gamePath.value===draft)gamePath.value=result.candidates[0].path;gameDetectMessage.value='已自动检测并保存游戏目录';tell(gameDetectMessage.value)}else if(automatic&&result.current_valid){gameDetectMessage.value='当前游戏目录有效'}else if(!detectedGames.value.length){gameDetectMessage.value='未找到游戏，请打开原游戏后重新检测，或手动浏览目录';if(automatic&&!modal.value)modal.value='directory'}else{gameDetectMessage.value=detectedGames.value.length===1?'已找到游戏，点击保存并识别即可使用':'检测到多个安装目录，请选择后保存';if(detectedGames.value.length===1&&gamePath.value===draft)gamePath.value=detectedGames.value[0].path;if(automatic&&!modal.value)modal.value='directory'}}catch(e){gameDetectMessage.value=e.message}finally{detectingGame.value=false}}
function cacheBytes(value){return value>=1073741824?(value/1073741824).toFixed(2)+' GB':value>=1048576?(value/1048576).toFixed(1)+' MB':value>=1024?(value/1024).toFixed(1)+' KB':value+' B'}
async function askPurge(record){purgeTarget.value=record;purgeInfo.value=null;purgeError.value='';modal.value='purge';try{const info=await execute('inspect_removed',{id:record.role.id});if(purgeTarget.value?.role.id===record.role.id)purgeInfo.value=info}catch(e){purgeError.value=e.message}}
async function purgeRemoved(){if(!purgeTarget.value||!purgeInfo.value)return;try{const result=await execute('delete_removed',{id:purgeTarget.value.role.id,confirmed:true,cleanup_token:purgeInfo.value.token});await refresh(false,true);purgeTarget.value=null;purgeInfo.value=null;modal.value='removed';tell('已删除角色私有缓存与记录，私有文件大小 '+cacheBytes(result.bytes))}catch(e){purgeInfo.value=null;purgeError.value=e.message}}
async function saveGame(){try{gamePath.value=await execute('game',{path:gamePath.value});await refresh();pathExpanded.value=false;modal.value='';tell('游戏目录已保存')}catch{}}
function navigate(next){if(next===page.value)return;if(next==='manager'){workspaceSelection={ids:[...checked.value],selected:selected.value,profiles:cloneJson(profiles.value),clean:!planDirty.value};checked.value=[];selected.value=''}else if(workspaceSelection){if(workspaceSelection.clean&&cfg.value.layout_plans?.[activePlan.value]){planName.value=activePlan.value;loadPlan()}else{checked.value=workspaceSelection.ids.filter(id=>roles.value.some(a=>a.id===id));selected.value=roles.value.some(a=>a.id===workspaceSelection.selected)?workspaceSelection.selected:'';profiles.value=Object.fromEntries(Object.entries(workspaceSelection.profiles).filter(([id])=>roles.value.some(a=>a.id===id)))}workspaceSelection=null}page.value=next;filter.value='';statusFilter.value='全部'}
function requestLauncherClose(){if(batchLaunching.value||busy.value||Object.values(launchFeedback.value).some(s=>s.phase==='requesting')){tell('当前操作正在处理，请稍后再关闭');return true}if(page.value==='manager')navigate('plans');if(planDirty.value){modal.value='close'}else raw('finish_close').catch(e=>tell(e.message));return true}
async function saveAndClose(){if(await savePlan())await raw('finish_close')}
onMounted(()=>{window.__requestLauncherClose=requestLauncherClose});
onUnmounted(()=>{delete window.__requestLauncherClose});
function canLeavePlan(){return !planDirty.value||confirm('当前启动方案有未保存修改，放弃这些修改并切换？')}
function switchPlan(name){if(!canLeavePlan())return;planName.value=name;loadPlan()}
function newPlan(force=false){if(!force&&!canLeavePlan())return;let name='新建方案',i=2;while(plans.value.includes(name))name=`新建方案 ${i++}`;planName.value=name;activePlan.value='';checked.value=[];selected.value='';profiles.value={};sizeDraft.value={width:960,height:540};settings.value={width:960,height:540,columns:3,gap:8,padding:8,aspect:true,mode:'网格排列'};auto.value=false;launchDelay.value=0;planGamePrefs.value=inheritGamePrefs();planBaseline.value=planFingerprint();schedulePreview()}
async function savePlan(){try{if(!checked.value.length){tell('请先为启动方案添加角色');return}if(planName.value!==activePlan.value&&plans.value.includes(planName.value)&&!confirm('已有同名启动方案，确认覆盖？'))return;await execute('save_plan',{...payload(),name:planName.value});await refresh();activePlan.value=planName.value;planBaseline.value=planFingerprint();tell('启动方案已保存，同一角色可加入多个方案');return true}catch{return false}}
function loadPlan(){const p=cfg.value.layout_plans?.[planName.value];if(!p)return;settings.value={width:960,height:540,columns:3,gap:8,padding:8,aspect:true,mode:'网格排列',...cloneJson(p.settings||{})};profiles.value=cloneJson(p.windows||{});checked.value=(p.roles||[]).filter(id=>roles.value.some(a=>a.id===id));selected.value=checked.value[0]||'';auto.value=!!p.auto;launchDelay.value=Number(p.launch_delay)||0;planGamePrefs.value=inheritGamePrefs(p.game_preferences);activePlan.value=planName.value;if(screens.value.some(s=>s.id===p.screen_device))screen.value=p.screen_device;else if(p.screen){const index=parseInt(p.screen)-1;if(screens.value[index])screen.value=screens.value[index].id}planBaseline.value=planFingerprint();schedulePreview()}
async function deletePlan(){if(!activePlan.value)return;if(!confirm(`删除启动方案“${activePlan.value}”？角色和账号缓存会保留。`))return;try{await execute('delete_plan',{name:activePlan.value});await refresh();if(plans.value.length){planName.value=plans.value[0];loadPlan()}else newPlan(true)}catch{}}
function openMembers(){memberDraft.value=[...checked.value];filter.value='';statusFilter.value='全部';modal.value='members'}
function confirmMembers(){checked.value=memberDraft.value.filter(id=>roles.value.some(a=>a.id===id));if(!checked.value.includes(selected.value))selected.value=checked.value[0]||'';modal.value='';schedulePreview()}
function removeMember(id){checked.value=checked.value.filter(key=>key!==id);if(selected.value===id)selected.value=checked.value[0]||''}
async function startSavedPlan(name){if(!canLeavePlan())return;planName.value=name;loadPlan();await start()}
async function arrange(){try{const n=await execute('arrange',payload());await refresh();tell(`已排列 ${n} 个窗口`)}catch{}}
async function restore(){try{const n=await execute('restore');tell(`已恢复 ${n} 个窗口位置`)}catch{}}
function planRunning(name){return (cfg.value.layout_plans?.[name]?.roles||[]).filter(id=>states.value[id]?.running).length}
async function closePlanWindows(name){try{const n=await execute('close_plan',{name,force:true});tell(n?`已关闭“${name}”的 ${n} 个游戏窗口`:'该方案没有可关闭的已跟踪窗口');await refresh()}catch{}}
async function closeMember(id){try{const n=await execute('close',{ids:[id],force:true});tell(n?`已关闭 ${nameFor(id)}`:'没有可关闭的已跟踪进程');launchFeedback.value[id]={phase:'done',error:''};await refresh()}catch{}}
async function closeRoles(all=false){try{const ids=all?roles.value.map(a=>a.id):targets.value;const n=await execute('close',{ids,force:true});tell(`已关闭 ${n} 个游戏窗口`);await refresh()}catch{}}
async function start(){
  if(queueBusy.value){queueOpen.value=true;tell('请等待当前队列完成，或停止后续启动');return}
  const options=payload(),ids=[...options.ids],seconds=Number(launchDelay.value);
  if(!ids.length){tell('请先为方案添加角色');return}
  if(!Number.isFinite(seconds)||seconds<0||seconds>300){tell('启动间隔需为 0～300 秒');return}
  if(ids.length>1&&ids.some(id=>!roles.value.find(a=>a.id===id)?.confirmed)){tell('待确认角色请一次只启动一个');return}
  queueOpen.value=true;
  try{await launchQueue.run(ids,{delay:seconds,layoutIds:ids,options:cloneJson(options),name:planName.value,names:Object.fromEntries(ids.map(id=>[id,nameFor(id)]))})}catch(e){tell(e.message)}
}


async function rebind(){try{const a=await execute('reset_legacy',{id:selected.value});modal.value='';await refresh();selected.value=a.id;checked.value=[a.id];if(page.value==='manager')await launchRole(a.id);else await start()}catch{}}
async function add(){try{const a=await execute('add');await refresh();selected.value=a.id;checked.value=[a.id];expanded.value.add(a.group||'未分组');binding.value=a.id;tell('请在新窗口登录并进入庭院，随后自动识别昵称和区服')}catch{}}
async function readRole(id=selected.value,quiet=false){if(!id||reading.value||readCandidate.value)return;reading.value=true;try{const candidate=await raw('read',{id});const role=roles.value.find(a=>a.id===id);if(role?.target_short_id&&(role.target_short_id!==candidate.short_id||role.target_server_id!==candidate.server_id))throw Error('当前登录角色与目标角色不符，请切换角色');readCandidate.value=candidate;readId.value=id;modal.value='confirm';binding.value=''}catch(e){if(!quiet)tell(e.message)}finally{reading.value=false}}
async function confirmRole(){try{await execute('confirm',{id:readId.value,identity:readCandidate.value});readCandidate.value=null;modal.value='';await refresh();tell('角色信息已确认保存')}catch{}}
function rejectRole(){readCandidate.value=null;modal.value='';binding.value=''}
async function openSync(){modal.value='sync';syncChecked.value=[];await scanSync()}
async function scanSync(){try{const r=await execute('scan_sync',{root:syncRoot.value});sources.value=r.accounts;syncRoot.value=r.root}catch{}}
async function browseSync(){const path=await window.pywebview.api.choose_folder();if(path){syncRoot.value=path;await scanSync()}}
async function sync(){try{const r=await execute('sync',{ids:syncChecked.value});const failures=r.filter(x=>x.error);await refresh();profiles.value=cloneJson(cfg.value.window_profiles||{});tell(failures.length?failures.map(x=>x.error).join('；'):`已同步 ${r.length} 个账号`);if(!failures.length)modal.value=''}catch{}}
function editRole(id){selected.value=id;const a=profiles.value[id]||{};const rect=preview.value.rects[id]||[preview.value.work[0]+8,preview.value.work[1]+8];editor.value={width:a.width||settings.value.width,height:a.height||settings.value.height,x:a.x??rect[0],y:a.y??rect[1]};modal.value='window'}
async function saveWindow(){profiles.value[selected.value]={...editor.value};modal.value='';schedulePreview();tell('已修改本方案的角色窗口设置，请保存方案')}
function rectStyle(rect){const w=preview.value.work;return {left:`${(rect[0]-w[0])/w[2]*100}%`,top:`${(rect[1]-w[1])/w[3]*100}%`,width:`${rect[2]/w[2]*100}%`,height:`${rect[3]/w[3]*100}%`}}
function press(e,id){if(e.button!==0)return;selected.value=id;const stage=e.currentTarget.parentElement.getBoundingClientRect();drag={id,sx:e.clientX,sy:e.clientY,stage,rects:cloneJson(preview.value.rects),frame:[...preview.value.frame],moved:false};e.currentTarget.setPointerCapture(e.pointerId)}
function move(e){if(!drag)return;const dx=e.clientX-drag.sx,dy=e.clientY-drag.sy;if(!drag.moved&&Math.abs(dx)+Math.abs(dy)<4)return;if(!drag.moved){for(const [id,r] of Object.entries(drag.rects))profiles.value[id]={x:r[0],y:r[1],width:r[2]-drag.frame[0],height:r[3]-drag.frame[1]};settings.value.mode='自定义坐标';drag.moved=true}const r=drag.rects[drag.id],w=preview.value.work;profiles.value[drag.id].x=Math.max(w[0],Math.min(w[0]+w[2]-r[2],Math.round(r[0]+dx/drag.stage.width*w[2])));profiles.value[drag.id].y=Math.max(w[1],Math.min(w[1]+w[3]-r[3],Math.round(r[1]+dy/drag.stage.height*w[3])));preview.value.rects[drag.id]=[profiles.value[drag.id].x,profiles.value[drag.id].y,r[2],r[3]]}
async function release(){if(!drag)return;const moved=drag.moved;drag=null;if(moved)tell('已调整本方案坐标，请保存方案；排列按钮才会移动游戏窗口')}
async function init(){if(ready.value)return;ready.value=true;try{await refresh(true);await updatePreview();detectGame(true);updateAction('startup');pollTimer=setInterval(()=>refresh().catch(()=>{}),3000);readTimer=setInterval(()=>{if(binding.value&&!busy.value&&!modal.value)readRole(binding.value,true)},10000)}catch(e){ready.value=false;tell(e.message)}}
onMounted(()=>{if(window.pywebview?.api)init();else window.addEventListener('pywebviewready',init,{once:true})});
onUnmounted(()=>{clearInterval(pollTimer);clearInterval(readTimer);clearTimeout(previewTimer)});
</script>

<template>
<div class="shell compact-workbench" :class="{'management-page':page==='manager',['role-view-'+roleView]:page==='manager'}">
 <aside class="sidebar">
  <div class="brand"><img class="brand-icon" :src="appIcon" alt="软件图标"><div><strong>{{brand.name}}</strong><small>本地账号 · 独立运行</small></div></div>
  <div class="nav-caption">工作台</div>
  <button class="nav-item" :class="{active:page==='plans'}" @click="navigate('plans')">▦ <span>启动方案</span><b>主</b></button>
  <button class="nav-item" :class="{active:page==='manager'}" @click="navigate('manager')">♙ <span>角色管理</span><em>{{roles.length}}</em></button>
  <div class="nav-caption second">工具与设置</div>
  <button class="nav-item" @click="openProxies">⇄ <span>代理管理</span></button>
  <button class="nav-item" @click="modal='directory'">⚙ <span>游戏目录</span></button>
  <button class="nav-item" @click="modal='logs'">≡ <span>运行记录</span></button>
  <button class="nav-item" @click="modal='help'">ⓘ <span>使用说明</span></button>
  <button class="nav-item" @click="modal='about'">♧ <span>关于与作者</span></button>
  <div class="sidebar-bottom"><p><i></i> 数据保存在本机</p><button v-if="updateInfo.release" class="update-available" @click="modal='about'">发现新版 v{{updateInfo.release.version}}</button><small>{{ready?'v'+brand.version+(brand.release_channel==='experimental'?' · 实验版':''):'正在连接本机服务…'}}</small></div>
 </aside>
 <main class="main">
  <header class="page-header"><div><div class="title-line"><h1>{{page==='plans'?'启动方案':'角色管理'}}</h1><span class="outline-badge">独立账号启动</span></div><p>已勾选 {{checked.length}} 个角色 · 运行中 {{running}} 个</p></div><div class="header-actions plan-main-actions" v-if="page==='plans'"><button class="primary" :disabled="busy||queueBusy||!ready||!checked.length" @click="start">{{batchLaunching?batchProgress:'启动当前组合'}} <span class="action-count">{{checked.length}}</span></button><button v-if="queueState.items.length" class="queue-trigger" :class="{active:queueBusy}" @click="queueOpen=!queueOpen" :aria-expanded="queueOpen">启动队列 {{queueReady}} / {{queueState.items.length}}<span v-if="queueFailed" class="queue-failure-count">{{queueFailed}} 失败</span></button><details class="close-actions"><summary :aria-disabled="busy" title="直接结束所选范围内的游戏，跳过游戏确认">关闭 ▾</summary><div class="workspace-action-menu"><button :disabled="busy||!targets.some(id=>states[id]?.running)" @click="closeRoles();$event.currentTarget.closest('details').open=false">关闭当前组合 <small>{{targets.filter(id=>states[id]?.running).length}} 个运行中</small></button><button v-if="planDirty&&activePlan" :disabled="busy||!planRunning(activePlan)" @click="closePlanWindows(activePlan);$event.currentTarget.closest('details').open=false" :title="'按已保存成员关闭：'+activePlan">关闭已保存方案 <small>{{activePlan}}</small></button><button class="close-all-action" :disabled="busy||!running" @click="closeRoles(true);$event.currentTarget.closest('details').open=false">关闭全部游戏 <small>{{running}} 个运行中</small></button></div></details></div><div class="header-actions" v-else><button v-if="queueState.items.length" class="queue-trigger" :class="{active:queueBusy}" @click="queueOpen=!queueOpen" :aria-expanded="queueOpen">启动队列 {{queueReady}} / {{queueState.items.length}}<span v-if="queueFailed" class="queue-failure-count">{{queueFailed}} 失败</span></button><button @click="add" :disabled="busy">＋ 添加角色</button><button class="primary" @click="openSync" :disabled="busy">从平安志同步</button></div><section class="launch-queue-panel" v-if="queueOpen&&queueState.items.length" aria-label="方案启动队列" @keydown.esc.stop="queueOpen=false"><div class="queue-heading"><div><strong :title="queueState.name">启动队列 · {{queueState.name}}</strong><small>{{queueState.dispatching?queueState.message:queuePending?'正在等待窗口就绪':'本轮已结束'}}</small></div><button class="queue-dismiss" @click="queueOpen=false" aria-label="收起启动队列">×</button></div><div class="queue-summary"><span>{{queueReady}} 已就绪</span><span>{{queuePending}} 等待中</span><span v-if="queueFailed" class="error">{{queueFailed}} 失败</span></div><div class="queue-task-list"><div v-for="(item,i) in queueState.items" :key="item.id" class="queue-task" :class="'queue-'+item.status"><span class="queue-index">{{i+1}}</span><div><strong>{{item.label||nameFor(item.id)}}</strong><small v-if="item.error" class="error">{{item.error}}</small><small v-else-if="item.status==='submitted'&&proxyRoutes[item.id]?.active">{{proxyPhase(proxyRoutes[item.id].phase)}}</small></div><span class="queue-status">{{queueStatus(item.status)}}</span></div></div><div class="queue-controls"><button v-if="queueState.dispatching" @click="stopLaunchQueue">停止后续启动</button><button @click="retryLaunchQueue" :disabled="queueBusy||!queueFailed">仅重试失败项<span v-if="queueFailed">（{{queueFailed}}）</span></button><button @click="clearLaunchQueue" :disabled="queueBusy">清除记录</button></div><p class="hint">停止只影响未提交的角色，已提交的游戏不会被关闭。重试保留本轮方案的尺寸、顺序和排列位置。</p></section></header>
  <p class="page-intro">{{page==='plans'?'为不同场景保存角色组合；同一角色可出现在多个方案中，共用一份账号缓存。':'统一管理角色身份、备注、分组与登录缓存；删除角色会同步移出所有启动方案。'}}</p>
  <section class="summary-card"><div><span class="count-dot"></span>已保存 <strong>{{cfg.accounts.length}}</strong> 个角色<span class="summary-sep">/</span>待确认 <strong>{{cfg.pending.length}}</strong> 个<span class="summary-sep">/</span>已勾选 <strong>{{checked.length}}</strong> 个<span class="summary-sep">/</span>运行中 <strong>{{running}}</strong> 个</div><div class="actions" v-if="page==='manager'"><button @click="add" :disabled="busy">＋ 添加角色</button><button class="primary" @click="openSync" :disabled="busy">⇄ 从平安志同步</button></div></section>
  <div class="workspace-grid" :class="{'manager-workspace':page==='manager'}">
   <div class="left-column">

    <section class="card launch-plans" v-if="page==='plans'"><div class="card-heading"><div><h2>方案列表</h2></div><button class="primary" @click="newPlan()">＋ 新建</button></div><div class="plan-list"><article v-for="n in plans" :key="n" class="plan-tile" :class="{active:activePlan===n,dragging:draggedPlan===n,'drop-target':dropPlan===n,'plan-landed':landedPlan===n}" :data-plan-name="n" draggable="true" @dragstart="beginPlanDrag($event,n)" @dragover="hoverPlanDrag($event,n)" @dragleave="dropPlan=''" @drop="dropScheme($event,n)" @dragend="finishPlanDrag" @keydown.alt.up.prevent="stepScheme(n,-1)" @keydown.alt.down.prevent="stepScheme(n,1)" title="拖动排序，也可聚焦后按 Alt + ↑ / ↓"><button class="plan-select" @click="switchPlan(n)"><strong>{{n}}</strong><span>{{(cfg.layout_plans[n].roles||[]).length}} 个角色 · {{cfg.layout_plans[n].settings?.mode||'网格排列'}}</span><small>{{(cfg.layout_plans[n].roles||[]).map(nameFor).join('、')||'暂无角色'}}</small></button></article><p v-if="!plans.length" class="hint">还没有启动方案，点击新建并添加角色。</p></div></section>
    <section class="card scheme-editor" :class="'member-view-'+memberView" v-if="page==='plans'"><div class="card-heading"><div><h2>方案成员 <span class="draft-badge" v-if="planDirty">未保存</span><span class="saved-badge" v-else-if="activePlan">已保存</span></h2><p class="hint">{{members.length}} 个角色 · 拖动排序，修改后保存方案。</p></div><div class="member-heading-tools"><div class="view-switch" role="group" aria-label="方案成员显示方式"><button v-for="v in [{id:'list',label:'列表'},{id:'cards',label:'卡片'},{id:'table',label:'表格'}]" :key="v.id" :class="{active:memberView===v.id}" :aria-pressed="memberView===v.id" :disabled="memberViewSaving" @click="chooseMemberView(v.id)">{{v.label}}</button></div><button @click="openMembers">＋ 角色</button></div></div><div class="scheme-name"><label><input aria-label="方案名称" v-model="planName" maxlength="60" placeholder="例如：日常六开、周末大号"></label><button class="primary" @click="savePlan" :disabled="busy">保存</button><button class="danger-outline" @click="deletePlan" :disabled="busy||!activePlan">删除</button></div><div class="scheme-members"><div class="member-table-head" v-if="memberView==='table'&&members.length"><span>昵称</span><span>区服</span><span>尺寸</span><span>状态</span><span>操作</span></div><div v-for="a in members" :key="a.id" class="scheme-member" :class="{focused:selected===a.id,'member-dragging':draggedMember===a.id,'member-drop-before':dropMember===a.id&&!memberDropAfter,'member-drop-after':dropMember===a.id&&memberDropAfter,'member-landed':landedMember===a.id}" :data-member-id="a.id" draggable="true" tabindex="0" @dragstart="beginMemberDrag($event,a.id)" @dragover="hoverMemberDrag($event,a.id)" @drop="dropMemberOrder($event,a.id)" @dragend="finishMemberDrag" @keydown.alt.up.prevent="stepMember(a.id,-1)" @keydown.alt.down.prevent="stepMember(a.id,1)" title="拖动排序；也可按 Alt + ↑ / ↓ 调整，修改后保存方案" @click="selected=a.id"><div><strong>{{a.nickname||a.name}}</strong><small :class="{error:!!launchError(a.id)}" :title="launchError(a.id)||a.server">{{launchError(a.id)||a.server||'待登录确认'}}</small></div><span class="member-server" :title="a.server">{{a.server||'待确认'}}</span><span class="member-size">{{roleSize(a)}}</span><small class="member-status" :title="'网络：'+proxyLabel(a.proxy_id)">{{status(a)}}</small><div class="member-actions"><button class="member-start" @click.stop="launchRole(a.id,true)" :disabled="busy||batchLaunching||isLaunching(a.id)" title="仅启动此角色，使用本方案的尺寸与位置">{{roleLaunchLabel(a)}}</button><button @click.stop="editRole(a.id)">设置</button><button class="member-close" @click.stop="closeMember(a.id)" :disabled="busy||!states[a.id]?.running" title="直接结束此角色的游戏进程，不弹游戏确认；未保存的本地设置可能丢失">关闭</button><button @click.stop="removeMember(a.id)">移出</button></div></div><div class="scheme-empty" v-if="!members.length"><p>为这个方案选择要启动的角色</p><button @click="openMembers">＋ 添加角色到方案</button></div></div><p class="hint">窗口尺寸与坐标独立保存在本方案中。修改后请保存；不会改变同一角色在其他方案中的设置。</p></section>
    <section class="card roles-card" v-if="page==='manager'"><div class="card-heading"><h2>角色列表 <span class="role-total">{{roles.length}}</span></h2><div class="role-heading-tools"><span class="muted">已保存 {{cfg.accounts.length}} · 待确认 {{cfg.pending.length}} · 已选 {{checked.length}}</span><div class="view-switch" role="group" aria-label="角色显示方式"><button v-for="v in [{id:'cards',label:'卡片'},{id:'list',label:'列表'},{id:'table',label:'表格'}]" :key="v.id" :class="{active:roleView===v.id}" :aria-pressed="roleView===v.id" :disabled="viewSaving" @click="chooseRoleView(v.id)">{{v.label}}</button></div></div></div>
     <div class="role-toolbar"><div class="search"><span>⌕</span><input v-model="filter" placeholder="搜索昵称、区服或备注"></div><select class="status-filter" v-model="statusFilter" aria-label="按角色状态筛选"><option v-for="s in ['全部','已就绪','运行中','待登录确认','需重新绑定']" :key="s">{{s}}</option></select><button @click="checked=visible.map(a=>a.id)">全选当前</button><button @click="checked=[]">取消全选</button><button @click="closeRoles()" :disabled="busy">关闭所选</button><button @click="openGroup('new')">＋ 新建分组</button><button @click="openProxyBinding" :disabled="!checked.length||busy">绑定代理</button><button class="danger-outline" @click="askRemove(checked)" :disabled="busy||!checked.length">删除所选（{{checked.length}}）</button><button @click="modal='removed'">已移除（{{removed.length}}）</button></div>
     <div class="group-drop-dock" v-if="draggedRole"><span>拖到分组：</span><div v-for="name in knownGroups" :key="name" class="group-drop-chip" :class="{over:roleDropGroup===name}" @dragover="hoverRoleGroup($event,name)" @drop="dropRoleGroup($event,name)">{{name}}</div></div>
     <div class="groups"><section class="account-group" :class="{'role-drop-target':roleDropGroup===g.name}" v-for="g in groups" :key="g.name" @dragover="hoverRoleGroup($event,g.name)" @drop="dropRoleGroup($event,g.name)"><div class="group-header"><button class="expand" @click="toggleExpanded(g.name)">{{expanded.has(g.name)?'▾':'▸'}}</button><input type="checkbox" :checked="groupCheck(g)" @change="toggleGroup(g)"><strong @click="toggleExpanded(g.name)">{{g.name}}</strong><span class="muted">{{g.roles.length}} 个角色 · {{g.roles.filter(a=>states[a.id]?.running).length}} 个运行中</span><div class="group-actions"><button @click="groupName=g.name;groupAction='assign';modal='group'">移入此组</button><button v-if="g.name!=='未分组'" @click="openGroup('rename',g.name)">重命名</button><button v-if="g.name!=='未分组'" @click="ungroup(g.name)">取消分组</button></div></div>
       <div class="group-roles" v-if="expanded.has(g.name)"><div class="role-table-heading" v-if="roleView==='table'&&g.roles.length"><span></span><span>昵称</span><span>区服</span><span>备注</span><span>状态</span><span>操作</span></div><div class="role-row" :class="{focused:selected===a.id,picked:checked.includes(a.id),'role-dragging':draggedRole===a.id,'role-landed':landedRole===a.id}" :data-role-id="a.id" draggable="true" @dragstart="beginRoleDrag($event,a.id)" @dragend="finishRoleDrag" title="拖动卡片可移入其他分组" v-for="a in g.roles" :key="a.id" @click="selected=a.id"><input type="checkbox" :value="a.id" v-model="checked" @click.stop><div class="role-identity"><strong :title="a.nickname||a.name">{{a.nickname||a.name}}</strong><small :title="a.server">{{a.server||'登录后读取区服'}}</small><small class="role-note" v-if="a.note&&!launchError(a.id)" :title="a.note">备注：{{a.note}}</small><small class="launch-error" v-if="launchError(a.id)" :title="launchError(a.id)">{{launchError(a.id)}}</small></div><span class="role-cell-server" :title="a.server">{{a.server||'待读取区服'}}</span><span class="role-cell-note" :title="a.note">{{a.note||'—'}}</span><span class="status" :title="'网络：'+proxyLabel(a.proxy_id)" :class="{live:states[a.id]?.running,pending:!a.confirmed}"><i></i>{{status(a)}}</span><div class="role-actions"><button class="role-start" :class="{starting:isLaunching(a.id)}" @click.stop="launchRole(a.id)" :disabled="busy||batchLaunching||isLaunching(a.id)">{{roleLaunchLabel(a)}}</button><button class="role-more-button" @click.stop="editMeta(a.id)" title="管理角色" aria-label="管理角色">⋯</button></div></div><div class="empty-group" v-if="!g.roles.length">此分组暂无角色，可将角色卡片拖到这里。</div></div>
      </section></div>
     <div class="role-footer"><span>{{binding?'正在等待新窗口登录，进入庭院后自动识别…':'在这里管理角色；启动与窗口排列请前往“启动方案”。'}}</span><button v-if="binding" @click="binding=''">暂停识别</button><button v-if="selected" @click="readRole()" :disabled="reading">{{reading?'读取中…':'读取角色信息'}}</button></div>
    </section>

   </div>
   <aside class="right-column" v-if="page==='plans'"><section class="card layout-card"><div class="card-heading"><div><h2>方案配置</h2></div><span class="section-number">02</span></div>
    <p class="current-scheme-label">正在编辑：<strong>{{planName}}</strong><span v-if="planDirty"> · 未保存</span></p>
    <div class="preview-heading"><strong>目标屏幕</strong><button @click="refresh();schedulePreview()">刷新屏幕</button></div><select v-model="screen"><option v-for="(s,i) in screens" :value="s.id" :key="s.id">{{i+1}}. {{s.work[2]}} × {{s.work[3]}}{{s.primary?' · 主屏幕':''}}</option></select>
    <p class="workarea-caption">可用区域 {{preview.work[2]}} × {{preview.work[3]}} px · 根据显示器自动读取</p>
    <div class="monitor-frame"><div class="monitor-top"><span>▣　排列预览</span><small>{{targets.length}} 个窗口</small></div><div class="stage" :style="{aspectRatio:`${preview.work[2]}/${preview.work[3]}`}"><div class="stage-window" :class="{chosen:id===selected,compact:r[2]/preview.work[2]<0.22}" :title="previewTitle(id,r)" v-for="(r,id,i) in preview.rects" :key="id" :style="rectStyle(r)" @pointerdown="press($event,id)" @pointermove="move" @pointerup="release" @pointercancel="release"><b>{{i+1}} {{nameFor(id)}}</b><small>{{states[id]?.running?'运行中':'未运行'}}</small></div></div><button class="enlarge" @click="navigate('plans');modal='layout'">↗ 放大编辑</button></div>
    <div class="preview-selection"><span class="selection-label">当前角色</span><template v-if="chosen"><strong>{{nameFor(selected)}}</strong><small>{{chosen.server||'待确认区服'}}</small></template><span v-else>点击预览或账号行选择角色</span></div>
    <div class="layout-modes"><button v-for="m in ['网格排列','错落排列','自定义坐标']" :class="{selected:settings.mode===m}" @click="settings.mode=m" :key="m"><span>{{settings.mode===m?'◉':'○'}}</span>{{m==='网格排列'?'整齐网格':m==='自定义坐标'?'玩家自定义':m}}</button></div>
    <section class="size-section compact-size"><div class="size-heading"><h3>窗口尺寸 <small>px</small></h3><label class="aspect-setting"><input type="checkbox" v-model="settings.aspect">锁定 16:9</label></div><div class="dimension-inputs"><label><span>宽度</span><input aria-label="游戏窗口宽度" type="number" min="160" step="16" v-model.number="sizeDraft.width"></label><span class="dimension-times">×</span><label><span>高度</span><input aria-label="游戏窗口高度" type="number" min="90" step="9" v-model.number="sizeDraft.height" :disabled="settings.aspect"></label></div><button class="primary size-apply" @click="applySizes" :disabled="busy||!checked.length">应用尺寸</button><p class="hint">修改后保存方案；点击“排列窗口”应用到游戏。</p></section>
    <h3 class="arrangement-title">排列参数</h3><div class="field-grid"><label>列数<input type="number" min="1" max="20" v-model.number="settings.columns" :disabled="settings.mode!=='网格排列'"></label><label>窗口间距<input type="number" min="0" v-model.number="settings.gap"></label><label>四周留白<input type="number" min="0" v-model.number="settings.padding"></label></div>
    <div class="layout-footer"><span class="layout-section-label">窗口布局</span><button @click="restore">恢复位置</button></div><button class="primary arrange-action" @click="arrange" :disabled="busy||!targets.length||!!previewError">一键排列 · {{targets.length}} 个窗口</button><section class="startup-options"><h3>启动选项</h3><div class="startup-controls"><label class="startup-auto"><input type="checkbox" v-model="auto">启动后自动排列</label><label class="launch-delay-setting"><span>启动间隔</span><div><input aria-label="方案启动间隔秒数" type="number" min="0" max="300" step="0.5" v-model.number="launchDelay" :disabled="batchLaunching"><span>秒</span></div></label></div><div class="game-preferences-entry"><button @click="openGamePrefs('plan')" :disabled="queueBusy" aria-label="修改当前方案游戏设置"><strong>方案游戏设置</strong><span :title="gamePrefsSummary">{{gamePrefsSummary}}</span><small>修改 ›</small></button><button class="game-global-entry" @click="openGamePrefs('global')" :disabled="queueBusy" :title="'全局默认：'+globalGamePrefsSummary">全局</button></div></section><p class="hint error" v-if="previewError">{{previewError}}</p>

   </section></aside>
  </div>
  <footer class="page-footer"><span>账号缓存与排列方案保存在本机</span><span>窗口操作仅针对本工具跟踪的进程</span></footer>
 </main>
 <Teleport to="body"><div v-if="floatingRole" ref="floatingEl" class="role-drag-float" :class="{settling:settlingRole}" :style="{transform:`translate3d(${floatPoint.x}px,${floatPoint.y}px,0)`}"><strong>{{floatingRole.nickname||floatingRole.name}}</strong><span>{{floatingRole.server||'待登录确认'}}</span><small>{{settlingRole?'正在落位…':dragKind==='member'?(dropMember?'放到「'+nameFor(dropMember)+'」'+(memberDropAfter?'后面':'前面'):'拖动调整方案成员顺序'):dragKind==='plan'?(dropPlan?'放到「'+dropPlan+'」附近':'拖动调整方案顺序'):(roleDropGroup?'放入「'+roleDropGroup+'」':'拖到目标分组')}}</small></div></Teleport>
 <Transition name="toast"><div class="toast" v-if="toast">{{toast}}</div></Transition>
 <div class="modal-mask" v-if="modal" @click.self="modal==='confirm'?rejectRole():modal=''">
  <section class="modal" :class="{wide:modal==='sync'||modal==='layout'||modal==='roles'||modal==='removed'||modal==='members'||modal==='proxies'||modal==='help','manual-dialog':modal==='help'}"><header><div><small class="eyebrow">{{brand.name}}</small><h2>{{({sync:'从平安志同步账号',group:groupAction==='assign'?'移入分组':groupAction==='rename'?'重命名分组':'新建分组',window:'独立窗口配置',confirm:'确认角色信息',layout:'排列预览与编辑',logs:'运行记录',help:'使用说明',about:'关于与作者',roles:'账号列表',directory:'游戏安装目录',gameprefs:gamePrefsScope==='global'?'全局游戏默认':'方案游戏设置',proxies:'代理管理',proxybind:'绑定角色代理',close:'方案尚未保存',members:'选择方案角色',meta:'管理角色',remove:'删除角色',removed:'已移除角色',purge:'永久删除角色与缓存',rebind:'重新绑定角色'})[modal]}}</h2></div><button class="modal-close" @click="modal==='confirm'?rejectRole():modal=''">×</button></header>
   <template v-if="modal==='gameprefs'"><p class="hint">{{gamePrefsScope==='global'?'全局默认供角色和方案继承，下次启动时生效。':'当前方案：'+planName+'。方案覆盖优先于角色设置，未覆盖项继续继承角色及全局。'}}</p><div v-if="gamePrefsScope==='global'" class="game-pref-options game-pref-dialog"><label><input type="checkbox" v-model="gamePrefs.mute_all" :disabled="gamePrefsWorking||queueBusy"><span><strong>关闭全部声音</strong><small>音乐、音效、视频和语音均关闭，音量归零。</small></span></label><label><input type="checkbox" v-model="gamePrefs.skip_intro" :disabled="gamePrefsWorking||queueBusy"><span><strong>关闭登录 / 开场动画</strong><small>使用游戏内的登录动画关闭选项。</small></span></label><label><input type="checkbox" v-model="gamePrefs.lowest_graphics" :disabled="gamePrefsWorking||queueBusy"><span><strong>最低画质</strong><small>30 帧、最低渲染档位，额外关闭抗锯齿。</small></span></label></div><div v-else class="scoped-game-preferences"><label v-for="field in prefFields" :key="field.key"><span>{{field.label}}</span><select v-model="gamePrefs[field.key]" :disabled="gamePrefsWorking||queueBusy"><option :value="null">继承角色设置</option><option :value="true">{{field.on}}</option><option :value="false">不强制，保留游戏设置</option></select></label></div><p class="hint">“不强制”会覆盖上级要求，保留当前游戏设置，不恢复历史值。已运行窗口需重启后生效。</p><footer><button @click="modal=''" :disabled="gamePrefsWorking">取消</button><button class="primary" @click="saveGamePrefs" :disabled="gamePrefsWorking||queueBusy">{{gamePrefsWorking?'保存中…':gamePrefsScope==='plan'?'应用到方案':'保存全局默认'}}</button></footer></template>
   <template v-if="modal==='close'"><p>“{{planName}}”有未保存的修改。关闭前是否保存？</p><p class="hint">关闭启动器不会关闭已经运行的游戏。</p><footer><button @click="modal=''">继续编辑</button><button class="danger-outline" @click="raw('finish_close').catch(e=>tell(e.message))">放弃修改并关闭</button><button class="primary" @click="saveAndClose" :disabled="busy">保存并关闭</button></footer></template>
   <template v-if="modal==='proxies'">
    <div class="feature-warning" role="note"><strong>⚠ 使用警告</strong><p>{{proxyRiskNotice}}</p></div>
    <div class="proxy-overview"><div><strong>角色代理</strong><p>在角色管理中绑定，之后直接使用角色或方案的启动按钮。</p></div><span class="proxy-capacity">{{proxyActiveCount}} {{proxyEngine.backend==='laoyu'?'个运行中':'/ 1 运行中'}}</span></div>
    <div class="proxy-provider"><label>代理执行<select v-model="backendDraft" :disabled="proxyWorking||proxyActiveCount>0"><option value="builtin">内置 TCP · 同时 1 个角色</option><option value="laoyu">老鱼专业版 · 本机 API</option></select></label><label v-if="backendDraft==='laoyu'">API 端口<input v-model.number="laoyuPort" type="number" min="1" max="65535" :disabled="proxyWorking||proxyActiveCount>0"></label><button @click="saveProxyBackend" :disabled="proxyWorking||proxyActiveCount>0">保存执行方式</button><button v-if="backendDraft==='laoyu'" @click="probeLaoYu" :disabled="proxyWorking">检测老鱼连接</button></div><p class="hint proxy-scope" v-if="laoyuInfo">{{laoyuInfo.ok?`已读取老鱼 ${laoyuInfo.lines} 条线路 · 新增 ${laoyuInfo.added||0} 条 · 已更新 ${laoyuInfo.updated||0} 条${laoyuInfo.skipped?' · 不支持的线路 '+laoyuInfo.skipped+' 条':''}`:laoyuInfo.error}}</p><p class="hint proxy-scope">当前使用：{{proxyEngine.backend==='laoyu'?'老鱼专业版。启动前自动同步或复用线路，并确认角色 PID 绑定；流量转发及 DNS、UDP 能力由老鱼设置决定。':'内置 IPv4 TCP；UDP / IPv6 不提供代理转发，DNS 接管暂停。'}}</p>
    <div class="proxy-workspace"><div class="proxy-pool"><div class="proxy-pool-tools"><button @click="editProxy()" :disabled="proxyWorking">＋ 添加 SOCKS5</button><button v-if="backendDraft==='laoyu'" @click="probeLaoYu" :disabled="proxyWorking">{{proxyWorking?'读取中…':'刷新老鱼线路'}}</button><button v-if="backendDraft==='laoyu'&&proxyEngine.laoyu_hidden" @click="restoreLaoYuLines" :disabled="proxyWorking">恢复已移除线路（{{proxyEngine.laoyu_hidden}}）</button></div><button class="proxy-pool-item" v-for="p in proxies" :key="p.id" :class="{active:proxyDraft.id===p.id}" @click="editProxy(p)" :disabled="proxyWorking"><strong>{{p.name}}</strong><small>{{p.host}}:{{p.port}}</small><small><span class="proxy-source-badge" v-if="p.laoyu_sign">{{p.laoyu_managed?'老鱼线路':'已关联老鱼'}}</span>{{p.laoyu_missing?'线路已移除':p.enabled?'已启用':'已停用'}} · {{roles.filter(a=>a.proxy_id===p.id).length}} 个角色绑定</small><small v-if="p.laoyu_exit_ip">出口 {{p.laoyu_exit_ip}}</small></button><p class="hint" v-if="!proxies.length">添加代理后，在角色管理中为角色选择它。</p></div>
    <div class="proxy-editor"><div class="field-grid two"><label>名称<input v-model="proxyDraft.name" maxlength="60" placeholder="例如：日常代理"></label><label>类型<input value="SOCKS5 · TCP" disabled></label><label>主机地址<input v-model="proxyDraft.host" :readonly="proxyDraft.laoyu_managed" placeholder="IP 或域名，不含协议"></label><label>端口<input type="number" min="1" max="65535" v-model="proxyDraft.port" :readonly="proxyDraft.laoyu_managed"></label><label>用户名<input v-model="proxyDraft.username" :readonly="proxyDraft.laoyu_managed" autocomplete="off" placeholder="留空保留已保存凭证"></label><label>密码<input type="password" v-model="proxyDraft.password" :readonly="proxyDraft.laoyu_managed" autocomplete="new-password" placeholder="留空保留已保存凭证"></label></div><p v-if="proxyDraft.laoyu_managed" class="hint">此线路由老鱼读取，地址和认证请在老鱼中修改后刷新；名称可在此重命名。<span v-if="proxyDraft.laoyu_exit_ip">老鱼检测出口：{{proxyDraft.laoyu_exit_ip}} {{proxyDraft.laoyu_area}}</span></p><div class="check-options" v-if="!proxyDraft.laoyu_managed"><label><input type="checkbox" v-model="proxyDraft.enabled">启用代理</label><label><input type="checkbox" v-model="proxyDraft.clear_auth">清除认证信息</label></div><div class="actions"><button class="primary" @click="saveProxy" :disabled="proxyWorking">保存代理</button><button v-if="proxyEngine.backend==='laoyu'" @click="syncLaoYu" :disabled="proxyWorking||!proxyDraft.id">同步此代理到老鱼</button><button @click="modal='';navigate('manager')">前往角色管理绑定</button><button v-if="proxyDraft.id" class="proxy-delete-button" @click="deleteProxyConfirm=!deleteProxyConfirm" :disabled="proxyWorking">删除代理</button><span class="hint">凭证仅在本机加密保存</span></div>
    <div v-if="deleteProxyConfirm" class="proxy-delete-confirm"><div><strong>移除“{{proxyDraft.name}}”？</strong><p v-if="roles.some(a=>a.proxy_id===proxyDraft.id)">此代理已被角色绑定，请先在下方角色管理中解除绑定或切换代理。</p><p v-else>只删除启动器中的记录，不删除老鱼原线路。<span v-if="proxyDraft.laoyu_sign">刷新时不会自动加回，可通过“恢复已移除老鱼线路”找回。</span></p></div><div class="actions"><button @click="deleteProxyConfirm=false">取消</button><button class="danger-outline" @click="deleteProxy" :disabled="proxyWorking||roles.some(a=>a.proxy_id===proxyDraft.id)">确认移除</button></div></div>
    <div class="proxy-bound-roles" v-if="proxyDraft.id"><span class="hint">已绑定角色</span><button v-for="a in roles.filter(a=>a.proxy_id===proxyDraft.id)" :key="a.id" @click="editMeta(a.id)">{{a.nickname||a.name}} · {{a.server||'待确认'}}</button><span class="hint" v-if="!roles.some(a=>a.proxy_id===proxyDraft.id)">暂无绑定</span></div>
    <details class="proxy-diagnostics"><summary>连接检测与诊断</summary><div class="actions"><button @click="testProxy()" :disabled="proxyWorking||!proxyDraft.id">{{proxyWorking?'检测中…':'检测代理连接'}}</button><button @click="testProxyDns" :disabled="proxyWorking||!proxyDraft.id">检测 DNS 通道</button></div><p class="hint">检测使用已保存配置，请先保存修改。</p><div v-if="proxyResult" class="proxy-test-result"><strong>TCP 连接：{{proxyResult.tcp?'通过':'未通过'}}</strong><p>出口 IP：{{proxyResult.exit_ip||'未取得'}} · {{proxyResult.latency_ms??'—'}} ms</p><p v-if="proxyResult.error" class="error">{{proxyResult.error}}</p><p v-if="proxyResult.exit_error" class="hint">{{proxyResult.exit_error}}（出口查询失败不等于 TCP 不可用）</p><p class="hint">UDP 协商：{{proxyResult.udp_associate?'通过':'未通过'}} · 数据往返：{{proxyResult.udp?'通过':'未通过'}}</p><p v-if="proxyResult.udp_error" class="hint">{{proxyResult.udp_error}}</p></div><div v-if="dnsResult" class="proxy-test-result"><strong>DNS 代理通道：{{dnsResult.ok?'通过':'未通过'}}</strong><p v-if="dnsResult.ok">加密解析成功 · {{dnsResult.latency_ms}} ms · 未回退本机 DNS</p><p v-else class="error">{{dnsResult.error}}</p><p class="hint">仅检测解析通道，游戏 DNS 自动接管未启用。</p></div></details>
    </div></div>
    <section class="proxy-runtime" v-for="route in proxySessions" :key="route.ticket"><div class="proxy-runtime-heading"><div><strong>{{nameFor(route.role_id)}}</strong><span>{{proxyPhase(route.phase)}}</span></div><button v-if="route.active" class="danger-outline" @click="closeProxyRole(route.role_id)" :disabled="busy">{{['starting','syncing_proxy','binding_proxy','creating_suspended_game','waiting_administrator'].includes(route.phase)?'取消启动':'关闭角色'}}</button></div><p v-if="route.phase==='failed'" class="error">{{route.message||'代理连接异常，请关闭角色后检查配置。'}}</p><details><summary>连接详情</summary><p v-if="route.provider==='laoyu'">老鱼 PID 线路：{{route.line_confirmed?'已确认':'等待确认'}} · 进程组 {{route.family_processes||0}} 个进程</p><template v-else><p>已转发 {{route.tcp_proxied||0}} · 已阻止 {{route.blocked||0}} · 外部直连记录 {{route.direct_external||0}} · 未分类 {{route.direct_unclassified||0}}</p><p class="hint">进程组 {{route.family_processes||0}} 个进程 · DNS 接管未启用。</p></template><p class="hint">运行状态表示组件绑定已确认，不等于完整出口或断线防泄漏验证。</p></details></section>
   </template>
   <template v-if="modal==='proxybind'"><div class="feature-warning" role="note" v-if="bindProxyId"><strong>⚠ 使用警告</strong><p>{{proxyRiskNotice}}</p></div><p>为 {{bindRoleIds.length}} 个勾选角色设置代理。</p><select v-model="bindProxyId" class="full-select"><option value="">直连</option><option v-for="p in proxies.filter(p=>p.enabled)" :key="p.id" :value="p.id">{{proxyOptionLabel(p)}}</option></select><p class="proxy-experiment" v-if="bindProxyId">保存后，角色和方案的启动按钮会按代理管理中选定的执行方式运行。内置 TCP 同时支持 1 个角色；老鱼专业版会为各角色分别绑定线路。</p><footer><button @click="modal=''">取消</button><button class="primary" @click="bindProxies" :disabled="busy">保存绑定</button></footer></template>
   <template v-if="modal==='directory'"><label class="field-label">游戏安装目录</label><div class="path-input"><input v-model="gamePath" placeholder="例如 D:\Game\yys"><button @click="chooseGame">浏览</button></div><div class="game-detect-actions"><button @click="detectGame()" :disabled="detectingGame||busy">{{detectingGame?'正在检测…':'自动检测游戏目录'}}</button><span class="hint" aria-live="polite">{{gameDetectMessage}}</span></div><div class="game-candidates" v-if="detectedGames.length"><button v-for="candidate in detectedGames" :key="candidate.path" @click="gamePath=candidate.path" :class="{chosen:gamePath===candidate.path}"><strong>{{candidate.path}}</strong><small>{{candidate.sources.join(' · ')}}</small></button></div><p class="hint">选择游戏根目录。已有有效配置会保留；检测到多个目录时由你选择。账号缓存仍保存在启动器目录下。</p><footer><button @click="modal=''">取消</button><button class="primary" @click="saveGame" :disabled="busy||detectingGame||!gamePath">保存并识别</button></footer></template>
   <template v-if="modal==='members'"><p class="hint">这里选择的是当前方案成员。同一个角色可以同时加入多个方案。</p><div class="path-input"><input v-model="filter" placeholder="搜索昵称、区服或备注"><button @click="memberDraft=[...new Set([...memberDraft,...visible.map(a=>a.id)])]">选中搜索结果</button><button @click="memberDraft=[]">清空选择</button></div><div class="sync-table"><div class="table-head"><span></span><span>角色昵称</span><span>区服</span><span>状态</span></div><label v-for="a in visible" :key="a.id"><input type="checkbox" v-model="memberDraft" :value="a.id"><strong>{{a.nickname||a.name}}<small v-if="a.note"> · {{a.note}}</small></strong><span>{{a.server||'待确认区服'}}</span><small>{{status(a)}}</small></label></div><footer><span>已选择 {{memberDraft.length}} 个角色</span><button @click="modal=''">取消</button><button class="primary" @click="confirmMembers">确认方案成员</button></footer></template>
   <template v-if="modal==='sync'"><div class="path-input"><input v-model="syncRoot"><button @click="browseSync">选择目录</button><button @click="scanSync">刷新</button></div><p class="hint">仅同步选中的平安志账号目录，来源保持不变；请先正常退出对应游戏窗口。</p><div class="sync-table"><div class="table-head"><span></span><span>角色昵称</span><span>区服</span><span>同步状态</span></div><label v-for="a in sources" :key="a.id"><input type="checkbox" :value="a.id" v-model="syncChecked"><strong>{{a.nickname}}</strong><span>{{a.server}}</span><small>{{roles.some(r=>r.pinganzhi_source_id===a.id)?'已同步 · 可更新':'可同步'}}</small></label></div><footer><span>已选 {{syncChecked.length}} / {{sources.length}} 个账号</span><button class="primary" @click="sync" :disabled="busy||!syncChecked.length">{{busy?'正在同步…':'同步所选账号'}}</button></footer></template>
   <template v-if="modal==='group'"><label class="field-label">分组名称</label><input v-model="groupName" placeholder="例如：常用角色、老板一组" @keyup.enter="saveGroup"><p class="hint" v-if="groupAction==='assign'">将 {{targets.length}} 个所选角色移入该分组。</p><footer><button class="primary" @click="saveGroup">保存分组</button></footer></template>
   <template v-if="modal==='window'"><div class="identity-banner"><strong>{{chosen?.nickname||chosen?.name}}</strong><span>{{chosen?.server}}</span></div><div class="field-grid two"><label>画面宽度<input type="number" min="160" v-model.number="editor.width"></label><label>画面高度<input type="number" min="90" v-model.number="editor.height"></label><label>屏幕 X 坐标<input type="number" v-model.number="editor.x"></label><label>屏幕 Y 坐标<input type="number" v-model.number="editor.y"></label></div><p class="hint">坐标使用目标屏幕的物理坐标，副屏可为负数；自定义模式使用此位置。</p><footer><button @click="modal=''">取消</button><button class="primary" @click="saveWindow" :disabled="busy">保存窗口配置</button></footer></template>
   <template v-if="modal==='confirm'&&readCandidate"><div class="identity-banner"><strong>{{readCandidate.nickname}}</strong><span>{{readCandidate.server}} · {{readCandidate.server_id}}</span></div><p>这些角色信息是否正确？确认后会保存当前独立登录缓存，下次可直接选择这个角色启动。</p><footer><button @click="rejectRole">不正确，重新选择</button><button class="primary" @click="confirmRole" :disabled="busy">信息正确，保存角色</button></footer></template>
   <template v-if="modal==='layout'"><p class="hint">拖动卡片调整位置，点击卡片选择角色；自定义坐标将自动保存。</p><div class="big-monitor"><div class="stage" :style="{aspectRatio:`${preview.work[2]}/${preview.work[3]}`}"><div class="stage-window" :class="{chosen:id===selected,compact:r[2]/preview.work[2]<0.22}" :title="previewTitle(id,r)" v-for="(r,id,i) in preview.rects" :key="id" :style="rectStyle(r)" @pointerdown="press($event,id)" @pointermove="move" @pointerup="release" @pointercancel="release"><b>{{i+1}} {{nameFor(id)}}</b><small>{{states[id]?.running?'运行中':'未运行'}}</small></div></div></div><p class="error" v-if="previewError">{{previewError}}</p><footer><button v-if="selected" @click="editRole(selected)">编辑所选角色</button><button class="primary" @click="arrange" :disabled="busy||!!previewError">应用到运行中窗口</button></footer></template>
   <template v-if="modal==='logs'"><div class="all-logs"><div v-for="(l,i) in logs" :key="i"><time>{{l.time}}</time> {{l.message}}</div></div></template>
   <template v-if="modal==='roles'"><div class="sync-table"><div class="table-head"><span></span><span>角色昵称</span><span>区服</span><span>状态</span></div><label v-for="a in roles" :key="a.id"><input type="checkbox" v-model="checked" :value="a.id"><strong>{{a.nickname||a.name}}</strong><span>{{a.server||'待读取'}}</span><small>{{status(a)}}</small></label></div><footer><button class="primary" @click="modal='';start()">启动所选角色</button></footer></template>
   <template v-if="modal==='meta'"><div class="identity-banner"><strong>{{chosen?.nickname||chosen?.name}}</strong><span>{{chosen?.server||'待确认区服'}}</span></div><label class="field-label">分组（可输入新名称）</label><input v-model="metaDraft.group" list="role-groups" maxlength="40"><datalist id="role-groups"><option v-for="g in knownGroups" :value="g" :key="g"/></datalist><label class="field-label">代理绑定</label><select class="full-select" v-model="metaDraft.proxy_id"><option value="">直连</option><option v-for="p in proxies" :key="p.id" :value="p.id">{{proxyOptionLabel(p)}}{{p.enabled?'':'（已停用）'}}</option></select><p class="hint" v-if="metaDraft.proxy_id">{{proxyEngine.message}}。保存后直接点击“启动”，由当前代理执行方式接管。内置模式需管理员授权；老鱼模式需专业版软件和本机 API 处于运行状态。</p><div class="feature-warning" role="note" v-if="metaDraft.proxy_id"><strong>⚠ 使用警告</strong><p>{{proxyRiskNotice}}</p></div><label class="field-label">角色游戏设置</label><div class="role-game-preferences"><label v-for="field in prefFields" :key="field.key"><span>{{field.label}}</span><select v-model="metaDraft.game_preferences[field.key]"><option :value="null">继承全局默认</option><option :value="true">{{field.on}}</option><option :value="false">不强制</option></select></label></div><p class="hint">单独启动使用角色设置；方案启动时方案覆盖优先。下次启动生效，“不强制”保留游戏当前设置。</p><section class="device-profile-settings"><label class="field-label">设备接口隔离 · 实验性</label><div class="feature-warning" role="note"><strong>⚠ 使用警告</strong><p>{{deviceRiskNotice}}</p></div><div class="device-status-row"><strong>{{devicePhaseLabel(deviceStatusFor(selected).phase)}}</strong><button v-if="states[selected]?.running" @click="checkDevice" :disabled="busy||deviceChecking">{{deviceChecking?'正在核验…':'检查当前窗口'}}</button></div><p class="hint" v-if="deviceStatusFor(selected).checked_at">核验时间：{{new Date(deviceStatusFor(selected).checked_at*1000).toLocaleTimeString('zh-CN',{hour12:false})}}</p><p class="hint" v-if="deviceStatusFor(selected).hint">{{deviceStatusFor(selected).hint}}</p><p class="hint error" v-if="deviceStatusFor(selected).error">{{deviceStatusFor(selected).error}}</p><p class="hint" v-if="deviceStatusFor(selected).api_calls?.length">接口调用：名称 {{deviceStatusFor(selected).api_calls[0]}} · 卷 {{deviceStatusFor(selected).api_calls[1]}} · 网卡 {{deviceStatusFor(selected).api_calls[2]}} / {{deviceStatusFor(selected).api_calls[3]}}。这是核验时的快照，不代表完整身份覆盖。</p><p class="hint">窗口就绪后启用。仅覆盖计算机名、卷序列号与两种网卡查询接口；不覆盖启动早期、固件、MachineGuid 或 SDK 缓存，不代表完整硬件身份隔离。</p><button @click="generateDeviceProfile" :disabled="busy||states[selected]?.running">{{metaDraft.device_identity?'重新生成参数':'生成独立设备参数'}}</button><template v-if="metaDraft.device_identity"><label class="device-enable"><input type="checkbox" v-model="metaDraft.device_identity.enabled" :disabled="states[selected]?.running">下次启动启用实验</label><dl><dt>设备名称</dt><dd>{{metaDraft.device_identity.computer_name}}</dd><dt>卷序列号</dt><dd>{{metaDraft.device_identity.volume_serial.toString(16).toUpperCase()}}</dd><dt>MAC 基值</dt><dd>{{metaDraft.device_identity.mac}}</dd></dl><p class="hint">同一角色在不同方案中共用这些参数。运行期间不能更改；开启可能导致客户端不兼容，初始化失败会关闭该角色。修改后点击保存。</p></template></section><label class="field-label">备注</label><textarea v-model="metaDraft.note" maxlength="200" rows="3" placeholder="例如：主号、日常号、用途说明"></textarea><p class="hint">备注仅保存在本机，不修改游戏昵称。{{metaDraft.note.length}} / 200 字</p><footer><button class="danger-outline" @click="askRemove([selected])">删除此角色</button><button class="primary" @click="saveMeta" :disabled="busy">保存</button></footer></template>
   <template v-if="modal==='remove'"><p>将从当前列表删除以下 {{removing.length}} 个角色，并移出排列方案。正在运行的角色需先退出游戏。</p><div class="removal-list"><div v-for="a in removing" :key="a.id"><strong>{{a.nickname||a.name}}</strong><span>{{a.server||'待确认区服'}}</span></div></div><p class="hint">本地账号缓存保留，平安志来源不变。可以在“已移除”中恢复；此操作不会释放磁盘空间。</p><footer><button @click="modal=''">取消</button><button class="primary" @click="removeRoles" :disabled="busy||!removing.length">确认删除 {{removing.length}} 个角色</button></footer></template>
   <template v-if="modal==='purge'&&purgeTarget"><div class="identity-banner"><strong>{{purgeTarget.role.nickname||purgeTarget.role.name}}</strong><span>{{purgeTarget.role.server||'待确认区服'}}</span></div><p>确认后将真正删除这个角色的私有登录缓存及已移除记录。无法从本工具恢复；再次使用需重新添加并登录。</p><section class="cleanup-summary" v-if="purgeInfo"><strong>待清理私有文件：{{cacheBytes(purgeInfo.bytes)}}</strong><p>{{purgeInfo.files}} 个文件 · {{purgeInfo.resource_links}} 个资源链接</p><code>{{purgeInfo.root}}</code><small>不计入共享游戏资源；硬链接文件和磁盘压缩可能影响实际释放空间。</small></section><p v-else-if="!purgeError" class="hint">正在统计私有缓存，请稍候…</p><p v-if="purgeError" class="error cleanup-error">{{purgeError}}</p><button v-if="purgeError" @click="askPurge(purgeTarget)" :disabled="busy">重新统计缓存</button><p class="hint">仅清理上方角色目录。资源链接只移除链接本身，原游戏资源、平安志来源和历史配置备份保留。</p><footer><button @click="modal='removed'" :disabled="busy">取消</button><button class="danger-outline" @click="purgeRemoved" :disabled="busy||!purgeInfo||!!purgeError">{{busy&&purgeInfo?'正在清理…':'确认删除并清理缓存'}}</button></footer></template>
   <template v-if="modal==='removed'"><p class="hint">这里保留已移除角色的记录及本地缓存。恢复角色不会恢复旧排列方案中的勾选状态。</p><div class="removed-list"><div v-for="a in removed" :key="a.role.id"><div><strong>{{a.role.nickname||a.role.name}}</strong><p>{{a.role.server||'待确认区服'}} · {{a.removed_at}}</p><small v-if="a.role.note">{{a.role.note}}</small></div><div class="removed-actions"><button @click="restoreRole(a.role.id)" :disabled="busy">恢复角色</button><button class="danger-outline" @click="askPurge(a)" :disabled="busy">永久删除并清理</button></div></div><p v-if="!removed.length" class="hint">暂无已移除角色。</p></div></template>
   <template v-if="modal==='rebind'"><p>此角色来自旧版混合缓存。将新建空白登录目录，旧目录保留；首次需要重新登录。</p><footer><button @click="modal=''">取消</button><button class="primary" @click="rebind">重新绑定并启动</button></footer></template>
   <template v-if="modal==='about'"><div class="about-content"><div class="about-hero"><img :src="appIcon" alt="僵尸痒痒鼠图标"><div><h3>{{brand.name}}</h3><p>{{brand.description}}</p><span class="about-version">v{{brand.version}} · Windows x64</span></div></div><section class="about-author"><span class="about-label">作者</span><strong>{{brand.author}}</strong><p>感谢使用 {{brand.name}}。希望它能让角色管理、多窗口启动和日常切换更方便。</p></section><dl class="about-facts"><div><dt>QQ</dt><dd class="author-contact">{{brand.qq}}</dd></div><div><dt>邮箱</dt><dd class="author-contact">{{brand.email}}</dd></div><div><dt>主要功能</dt><dd>独立角色登录环境、启动方案、窗口排列、游戏偏好与角色代理</dd></div><div><dt>数据保存</dt><dd>角色、方案和代理配置保存在本机软件目录中</dd></div><div><dt>运行方式</dt><dd>Windows EXE 入口 · Python 后端 · Vue 界面</dd></div></dl><p class="about-note">本工具不包含游戏本体。游戏及第三方组件的名称、素材与版权归相应权利人所有。</p><section class="app-update"><h3>软件更新 <small>当前 v{{brand.version}}</small></h3><label><input type="checkbox" :checked="updateInfo.auto_check" @change="updateAction('settings',{auto_check:$event.target.checked})"> 启动时自动检查更新</label><p aria-live="polite">{{updateInfo.message}}</p><p class="error" v-if="updateInfo.error">{{updateInfo.error}}</p><p v-if="updateInfo.release"><strong>v{{updateInfo.release.version}}</strong> · {{updateInfo.release.experimental?'测试版本':'正式版本'}} · {{(updateInfo.release.size/1048576).toFixed(1)}} MB</p><progress v-if="updateInfo.phase==='downloading'" :value="updateInfo.received" :max="updateInfo.total||1"></progress><pre v-if="updateInfo.release" class="update-notes">{{updateInfo.release.notes}}</pre><div class="update-actions"><button @click="updateAction('check')" :disabled="updateBusy">{{updateInfo.phase==='checking'?'正在检查…':'检查更新'}}</button><button class="primary" v-if="updateInfo.release&&updateInfo.phase!=='downloaded'" @click="updateAction('download')" :disabled="updateBusy">{{updateInfo.phase==='downloading'?'正在下载…':'下载新版'}}</button><button v-if="updateInfo.phase==='downloaded'" @click="updateAction('folder')">打开下载目录</button><button @click="updateAction('page')">GitHub 发布页</button></div><p class="hint">自动检查仅访问本项目的公开更新信息，不发送账号与代理信息。下载包校验通过后，按手册备份数据并升级；不会自动覆盖当前程序。</p></section><div class="about-links"><button @click="modal='help'">阅读使用手册</button><span>作者：{{brand.author}} · v{{brand.version}}</span></div></div></template>
   <template v-if="modal==='help'"><div class="manual-content" v-html="userManual"></div></template>
  </section>
 </div>
 <div class="connecting" v-if="!ready"><span class="spinner"></span>正在连接本机启动服务…</div>
</div>
</template>
